    @Override public BigInteger getPowerExact(){var binding=com.hbm.multiblock.proxy.SourceProxyBindings.get(this);if(binding!=null){return binding.getPowerExact();}var c=core();return c==null?BigInteger.ZERO:c.getPowerExact();}
    @Override public BigInteger getMaxPowerExact(){var binding=com.hbm.multiblock.proxy.SourceProxyBindings.get(this);if(binding!=null){return binding.getMaxPowerExact();}var c=core();return c==null?BigInteger.ZERO:c.getMaxPowerExact();}
    @Override public void setPowerExact(BigInteger value){var binding=com.hbm.multiblock.proxy.SourceProxyBindings.get(this);if(binding!=null){binding.setPowerExact(value);return;}var c=core();if(c!=null)c.setPowerExact(value);}
